import { defineConfig, mergeConfig } from 'vitest/config';
import base from './vitest.config';

/**
 * Vitest config used only by Stryker.
 *
 * The production config collects v8 coverage and enforces thresholds. Stryker
 * re-runs the whole suite once per mutant, so paying for coverage every time is
 * the dominant cost of a run — and Stryker derives its own coverage from the
 * dry run anyway. Single fork because mutant testing needs deterministic,
 * single-process execution.
 *
 * Generated by scripts/scaffold-stryker.ts; never overwritten once it exists.
 */
export default mergeConfig(
  base,
  defineConfig({
  resolve: { conditions: ['source', 'import', 'module', 'node', 'default'] },
    test: {
      coverage: { enabled: false },
      reporters: ['default'],
      pool: 'forks',
      maxWorkers: 1,
      fileParallelism: false,
    },
  }),
);
